14	  "data",
15	  "inference",
16	  "chip",
17	  "cloud",
18	  "software",
19	  "research",
20	  "policy"
21	];
22	
23	const WEAK_PATTERNS = [
24	  "top 10",
25	  "ultimate guide",
26	  "you won't believe",
27	  "make money",
28	  "crypto giveaway",
29	  "coupon",
30	  "sponsored"
31	];
32	
33	const BEAT_KEYWORDS = {
34	  security: [
35	    "security",
36	    "vulnerability",
37	    "exploit",
38	    "attack",
39	    "prompt injection",
40	    "jailbreak",
41	    "sandbox",
42	    "red team",
43	    "privacy",
44	    "leak",
45	    "supply chain",
46	    "auth",
47	    "malware",
48	    "risk"
49	  ],
50	  robotics: ["robot", "robotics", "embodied", "sensor", "actuator", "navigation", "manipulation"],
51	  ethics: ["ethics", "governance", "policy", "bias", "transparency", "accountability", "rights"],
52	  developer: ["developer", "sdk", "api", "open source", "tooling", "framework", "library"],
53	  "machine learning": ["training", "inference", "benchmark", "dataset", "model", "gradient", "evaluation"]
54	};
55	
56	function domainTerms(domain) {
57	  return normalizeText(domain).split(" ").filter(Boolean);
58	}
59	
60	function beatTerms(domain) {
61	  const normalized = normalizeText(domain);
62	  const matched = Object.entries(BEAT_KEYWORDS).find(([key]) => normalized.includes(key));
63	  return matched ? matched[1] : domainTerms(domain);
64	}
65	
66	function scoreTopic(topic, state, now = new Date()) {
67	  const title = normalizeText(topic.title);
68	  const summary = normalizeText(topic.summary);
69	  const combined = `${title} ${summary}`;
70	  const personaTerms = domainTerms(state.agent.persona.domain);
71	  const specificBeatTerms = beatTerms(state.agent.persona.domain);
72	  const previousTexts = state.posts.map((post) => `${post.text} ${post.rationale}`);
73	
74	  let score = 0;
75	  const reasons = [];
76	  const rejectionReasons = [];
77	
78	  const hasTechSignal = TECH_KEYWORDS.some((keyword) => combined.includes(keyword));
79	  if (hasTechSignal) {
80	    score += 2;
81	    reasons.push("it is clearly within AI or technology");
82	  } else {
83	    rejectionReasons.push("it does not have a strong AI or technology signal");
84	  }
85	
86	  const personaMatches = personaTerms.filter((term) => combined.includes(term)).length;
87	  const beatMatches = specificBeatTerms.filter((term) => combined.includes(term)).length;
88	  if (personaMatches > 0) {
89	    score += Math.min(3, personaMatches * 1.5);
90	    reasons.push(`it matches the persona's ${state.agent.persona.domain} focus`);
91	  } else {
92	    score -= 1;
93	    rejectionReasons.push(`it is not close enough to the ${state.agent.persona.domain} beat`);
94	  }
95	
96	  if (beatMatches > 0) {
97	    score += Math.min(2.5, beatMatches * 1.25);
98	    reasons.push("it contains specific beat-level signals rather than generic AI relevance");
99	  } else if (personaTerms.length > 1) {
100	    score -= 4.5;
101	    rejectionReasons.push(`it mentions AI or technology but lacks the specific ${state.agent.persona.domain} angle`);
102	  }
103	
104	  const ageHours = hoursBetween(topic.publishedAt, now);
105	  if (ageHours <= 24) {
106	    score += 2;
107	    reasons.push("it is fresh within the last 24 hours");
108	  } else if (ageHours <= 96) {
109	    score += 1;
110	    reasons.push("it is still recent enough to be timely");
111	  } else {
112	    score -= 2;
113	    rejectionReasons.push("it is too old for a live feed");
114	  }
115	
116	  const points = topic.signals?.points || 0;
117	  const comments = topic.signals?.comments || 0;
118	  if (points + comments >= 20) {
119	    score += 1.5;
120	    reasons.push("it shows meaningful community attention");
121	  } else if (topic.sourceName === "arXiv") {
122	    score += 1;
123	    reasons.push("it is primary research rather than engagement bait");
124	  } else {
125	    rejectionReasons.push("it has limited evidence of external importance");
126	  }
127	
128	  const publishedUrls = new Set(state.posts.flatMap((post) => post.sources || []));
129	  if (publishedUrls.has(topic.url)) {
130	    score -= 5;
131	    rejectionReasons.push("it has already been published");
132	  } else if (state.seenTopics.some((item) => item.url === topic.url)) {
133	    score -= 1;
134	    rejectionReasons.push("it was considered in an earlier discovery cycle");
135	  }
136	
137	  const repeated = previousTexts.some((text) => similarity(topic.title, text) > 0.32);
138	  if (repeated) {
139	    score -= 4;
140	    rejectionReasons.push("it is too similar to earlier published content");
141	  } else {
142	    score += 1;
143	    reasons.push("it adds a new angle to the feed memory");
144	  }
145	
146	  if (WEAK_PATTERNS.some((pattern) => combined.includes(pattern))) {
147	    score -= 4;
148	    rejectionReasons.push("it reads like low-signal promotional content");
149	  }
150	
151	  if (topic.title.length < 18) {
152	    score -= 1;
153	    rejectionReasons.push("the topic is too thinly described");
154	  }
155	
156	  return {
157	    topic,
158	    score,
159	    reasons,
160	    rejectionReasons
161	  };
162	}
163	
164	export function evaluateTopics(topics, state, now = new Date()) {
165	  const scored = topics.map((topic) => scoreTopic(topic, state, now));
166	  const accepted = scored
167	    .filter((item) => item.score >= 4.5)
168	    .sort((a, b) => b.score - a.score);
169	
170	  const rejected = scored
171	    .filter((item) => item.score < 4.5)
172	    .sort((a, b) => b.score - a.score)
173	    .slice(0, 10)
174	    .map((item) => ({
175	      title: item.topic.title,
176	      url: item.topic.url,
177	      score: Number(item.score.toFixed(2)),
178	      rejectedAt: now.toISOString(),
179	      reason: item.rejectionReasons[0] || "it did not clear the editorial threshold"
180	    }));
181	
182	  return {
183	    selected: accepted[0] || null,
184	    rejected,
185	    scored
186	  };
187	}
