}

export function createId(prefix) {
  return `${prefix}-${randomUUID().slice(0, 8)}`;
}

export function normalizeText(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/https?:\/\/\S+/g, " ")
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function tokenize(value) {
  const stop = new Set([
    "the",
    "and",
    "for",
    "with",
    "that",
    "this",
    "from",
    "into",
    "are",
    "was",
    "were",
    "has",
    "have",
    "will",
    "about",
    "over",
    "after",
    "before",
    "using",
    "new"
  ]);

  return normalizeText(value)
    .split(" ")
    .filter((word) => word.length > 2 && !stop.has(word));
