  { method: "GET", path: "/", handler: handleRoot },
  { method: "GET", path: "/health", handler: handleHealth },
  { method: "POST", path: "/api/agent/init", handler: handleInit },
  { method: "GET", path: "/api/agent/feed", handler: handleFeed }
];

