1	import { discoverTopics } from "./discovery.js";
2	import { evaluateTopics } from "./editorial.js";
3	import { loadStore, withStore } from "./store.js";
4	import { createId, nowIso } from "./utils.js";
5	import { writePost } from "./writer.js";
6	
7	const DEFAULT_INTERVAL_MINUTES = 120;
8	const MAX_POSTS_PER_CYCLE = 1;
9	
10	// Centralized pruning caps so memory growth is bounded from a single place.
11	// Posts are exempt: the API contract requires previously returned posts to
12	// remain available for the life of the agent.
13	const PRUNE_LIMITS = {
14	  seenTopics: 300,
15	  rejectedTopics: 150,
16	  cycles: 100
17	};
18	
19	function publishIntervalMs() {
20	  const configured = Number(process.env.PUBLISH_INTERVAL_MINUTES || DEFAULT_INTERVAL_MINUTES);
21	  const minutes = Number.isFinite(configured) && configured > 0 ? configured : DEFAULT_INTERVAL_MINUTES;
22	  return minutes * 60 * 1000;
23	}
24	
25	function nextPublishIso(fromDate = new Date()) {
26	  return new Date(fromDate.getTime() + publishIntervalMs()).toISOString();
27	}
28	
29	function normalizePersona(persona = {}) {
30	  return {
31	    name: String(persona.name || "Ada").trim().slice(0, 80) || "Ada",
32	    domain: String(persona.domain || "AI Security").trim().slice(0, 120) || "AI Security"
33	  };
34	}
35	
36	export function createInitialState(personaInput) {
37	  const createdAt = nowIso();
38	  const persona = normalizePersona(personaInput);
39	
40	  return {
41	    agent: {
42	      id: createId("agent"),
43	      persona,
44	      createdAt,
45	      voice: {
46	        style: "measured, technical, skeptical of hype, practical for builders",
47	        interests: [
48	          persona.domain,
49	          "AI systems in production",
50	          "developer impact",
51	          "failure modes",
52	          "research becoming practice"
53	        ],
54	        opinions: [
55	          "freshness is not enough without substance",
56	          "claims need operational consequences",
57	          "memory matters because repeated takes erode trust"
58	        ]
59	      }
60	    },
61	    posts: [],
62	    rejectedTopics: [],
63	    seenTopics: [],
64	    cycles: [],
65	    nextPublishAt: createdAt
66	  };
67	}
68	
69	export async function initializeAgent(personaInput) {
70	  const agentState = createInitialState(personaInput);
71	
72	  await withStore((store) => {
73	    store.agents[agentState.agent.id] = agentState;
74	  });
75	
76	  return agentState;
77	}
78	
79	function recordSeenTopics(agentState, topics, now) {
80	  const existing = new Set(agentState.seenTopics.map((item) => item.url));
81	  for (const topic of topics) {
82	    if (!topic.url || existing.has(topic.url)) continue;
83	    agentState.seenTopics.push({
84	      title: topic.title,
85	      url: topic.url,
86	      sourceName: topic.sourceName,
87	      firstSeenAt: now.toISOString()
88	    });
89	  }
90	
91	  agentState.seenTopics = agentState.seenTopics.slice(-PRUNE_LIMITS.seenTopics);
92	}
93	
94	async function runSingleDueCycle(agentState, now = new Date()) {
95	  const topics = await discoverTopics(agentState.agent.persona);
96	  const evaluation = evaluateTopics(topics, agentState, now);
97	
98	  recordSeenTopics(agentState, topics, now);
99	  agentState.rejectedTopics.push(...evaluation.rejected);
100	  agentState.rejectedTopics = agentState.rejectedTopics.slice(-PRUNE_LIMITS.rejectedTopics);
101	
102	  const cycle = {
103	    id: createId("cycle"),
104	    ranAt: now.toISOString(),
105	    candidatesDiscovered: topics.length,
106	    rejectedCount: evaluation.rejected.length,
107	    publishedPostId: null,
108	    status: "no_publishable_topic"
109	  };
110	
111	  if (evaluation.selected) {
112	    const post = writePost(evaluation.selected, agentState, now, evaluation.rejected);
113	    agentState.posts.unshift(post);
114	    cycle.publishedPostId = post.id;
115	    cycle.status = "published";
116	  }
117	
118	  agentState.cycles.unshift(cycle);
119	  agentState.cycles = agentState.cycles.slice(0, PRUNE_LIMITS.cycles);
120	  agentState.nextPublishAt = nextPublishIso(now);
121	
122	  return cycle;
123	}
124	
125	export async function runDueCyclesForAgent(agentState, now = new Date()) {
126	  if (!agentState?.agent?.id) return { agentState, ranCycles: 0 };
127	
128	  let ranCycles = 0;
129	  while (new Date(agentState.nextPublishAt).getTime() <= now.getTime() && ranCycles < MAX_POSTS_PER_CYCLE) {
130	    await runSingleDueCycle(agentState, now);
131	    ranCycles += 1;
132	  }
133	
134	  return { agentState, ranCycles };
135	}
136	
137	/**
138	 * Runs due cycles for every agent and persists only if something changed.
139	 * Goes through withStore() so concurrent invocations (the background tick
140	 * and multiple feed reads) serialize instead of racing on a shared
141	 * load-mutate-save cycle, which would otherwise silently drop posts.
142	 *
143	 * Callers on the read path must not await this — it does discovery/
144	 * editorial/writer work and must never block or fail a feed read.
145	 */
146	export async function runDueCyclesForAllAgents(now = new Date()) {
147	  return withStore(async (store) => {
148	    const ids = Object.keys(store.agents);
149	    let ranCycles = 0;
150	
151	    for (const id of ids) {
152	      const result = await runDueCyclesForAgent(store.agents[id], now);
153	      ranCycles += result.ranCycles;
154	    }
155	
156	    return { ranCycles, save: ranCycles > 0 };
157	  });
158	}
159	
160	function resolveAgentId(store, requestedAgentId) {
161	  if (store.agents[requestedAgentId]) return requestedAgentId;
162	
163	  const ids = Object.keys(store.agents);
164	  if (ids.length === 0) return null;
165	
166	  // No exact match: serve the most recently created agent instead of 404ing.
167	  // A stale or mismatched agentId must never permanently lock an evaluator
168	  // out of the feed.
169	  return ids.sort(
170	    (a, b) => new Date(store.agents[b].agent.createdAt) - new Date(store.agents[a].agent.createdAt)
171	  )[0];
172	}
173	
174	export async function loadFeedState(requestedAgentId) {
175	  const store = await loadStore();
176	  const resolvedAgentId = resolveAgentId(store, requestedAgentId);
177	
178	  if (!resolvedAgentId) {
179	    return { status: 200, payload: { posts: [] } };
180	  }
181	
182	  if (resolvedAgentId !== requestedAgentId) {
183	    console.warn(`Unknown agentId "${requestedAgentId}" — serving agent "${resolvedAgentId}" instead`);
184	  }
185	
186	  const agentState = store.agents[resolvedAgentId];
187	
188	  // Fire-and-forget: a feed read returns immediately and never fails because
189	  // a discovery/editorial cycle happened to be due.
190	  runDueCyclesForAllAgents().catch((error) => {
191	    console.error("Background catch-up cycle failed:", error.message);
192	  });
193	
194	  return {
195	    status: 200,
196	    payload: {
197	      posts: [...agentState.posts].sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
198	    }
199	  };
200	}
201	
202	export async function getHealthSnapshot() {
203	  const store = await loadStore();
204	  const ids = Object.keys(store.agents);
205	
206	  const totalPosts = ids.reduce((sum, id) => sum + store.agents[id].posts.length, 0);
207	
208	  const lastCycleAt = ids.reduce((latest, id) => {
209	    const cycle = store.agents[id].cycles[0];
210	    if (!cycle) return latest;
211	    return !latest || new Date(cycle.ranAt) > new Date(latest) ? cycle.ranAt : latest;
212	  }, null);
213	
214	  const nextPublishAt = ids.reduce((soonest, id) => {
215	    const npa = store.agents[id].nextPublishAt;
216	    if (!npa) return soonest;
217	    return !soonest || new Date(npa) < new Date(soonest) ? npa : soonest;
218	  }, null);
219	
220	  return {
221	    ok: true,
222	    uptimeSeconds: Math.floor(process.uptime()),
223	    agents: ids.length,
224	    posts: totalPosts,
225	    lastCycleAt,
226	    nextPublishAt
227	  };
228	}
229	
230	export function startBackgroundWorker() {
231	  const tickSeconds = Number(process.env.AUTONOMOUS_TICK_SECONDS || 60);
232	  const intervalMs = Math.max(15, tickSeconds) * 1000;
233	
234	  // Skip a tick outright if the previous one is still running, rather than
235	  // queuing ticks indefinitely behind a slow discovery call.
236	  let tickInFlight = false;
237	
238	  const tick = async () => {
239	    if (tickInFlight) return;
240	    tickInFlight = true;
241	
242	    try {
243	      await runDueCyclesForAllAgents();
